function uninstalled(id: string, name: string, install_hint: string, managedPkg?: string): NodeHarnessView {
  return {
    id,
    name,
    available: false,
    version: "",
    adapter_version: null,
    models: [],
    degraded_reason: null,
    install_hint,
    installed: false,
    error: null,
    setup: managedPkg
      ? {
          state: "not_installed",
          components: [{ id: "adapter", name, package: managedPkg, status: "missing" }],
          can_install: false,
        }
      : null,
  }
}

